<template><div class="space-y-6"><div><h1 class="text-xl font-bold text-slate-900">Registrar Entrada de Inventario</h1><p class="text-xs text-slate-500">Recepción de mercadería de proveedores</p></div><div v-if="error" class="rounded-lg bg-red-50 border border-red-200 text-red-700 p-3 text-xs">{{error}}</div><div class="bg-white p-5 rounded-xl border border-slate-200 shadow-sm grid grid-cols-3 gap-4"><label>Proveedor Activo<select v-model="supplier"><option v-for="s in suppliers" :key="s.id_proveedor" :value="s.id_proveedor">{{s.nombre}}</option></select></label><label>Fecha de Recepción<input v-model="date" type="date"></label><label>Documento de Referencia<input v-model="doc" placeholder="Ej: FAC-99082"></label></div><div class="bg-white p-4 rounded-xl border border-slate-200 shadow-sm space-y-3"><h3 class="text-xs font-bold uppercase text-slate-600">Agregar Producto a la Entrada</h3><div class="grid grid-cols-12 gap-3 items-end"><label class="col-span-5 normal">Producto<select v-model="line.code"><option v-for="p in products" :key="p.id_producto" :value="p.id_producto">{{p.codigo}} - {{p.nombre}}</option></select></label><label class="col-span-2 normal">Cantidad<input v-model.number="line.qty" type="number" min="0.01" step="0.01"></label><label class="col-span-3 normal">Costo Unitario ($)<input v-model.number="line.cost" type="number" min="0" step="0.01"></label><button @click="add" class="col-span-2 w-full py-2 bg-emerald-600 hover:bg-emerald-700 text-white rounded-lg text-xs font-semibold">+ Agregar Línea</button></div></div><div class="bg-white rounded-xl border border-slate-200 shadow-sm p-5 space-y-4"><table class="w-full text-left"><thead><tr class="bg-slate-100 text-slate-600 text-xs uppercase border-b"><th class="p-3">Código</th><th class="p-3">Producto</th><th class="p-3 text-center">Cantidad</th><th class="p-3 text-right">Costo U.</th><th class="p-3 text-right">Subtotal</th></tr></thead><tbody class="text-xs"><tr v-for="(i,n) in cart" :key="n"><td class="p-3 font-mono">{{product(i.code).codigo}}</td><td class="p-3 font-semibold">{{product(i.code).nombre}}</td><td class="p-3 text-center">{{i.qty}}</td><td class="p-3 text-right">{{money(i.cost)}}</td><td class="p-3 text-right font-bold">{{money(i.qty*i.cost)}}</td></tr><tr v-if="!cart.length"><td colspan="5" class="p-6 text-center text-slate-400">Sin ítems agregados a esta entrada.</td></tr></tbody></table><div class="flex justify-between items-center pt-4 border-t"><span class="text-sm font-bold">TOTAL ENTRADA: {{money(total)}}</span><button @click="confirm" :disabled="!cart.length" class="px-6 py-2.5 bg-[#F28C28] text-white rounded-lg text-xs font-bold disabled:opacity-50">Confirmar Entrada</button></div></div><div v-if="modal" class="modal"><div class="modal-card max-w-lg"><div class="modal-head"><h3>ENTRADA REGISTRADA</h3><button @click="modal=false"><i class="fa-solid fa-xmark text-lg"></i></button></div><div class="p-6 text-center space-y-3"><div class="inline-flex p-3 bg-emerald-100 text-emerald-600 rounded-full"><i class="fa-solid fa-truck-ramp-box text-3xl"></i></div><h3 class="font-bold">Entrada procesada con Correlativo: <span class="font-mono text-[#1F3A5F]">{{correlativo}}</span></h3><p class="text-xs text-slate-600">El stock de los productos ha sido incrementado debidamente en el sistema.</p><button @click="modal=false" class="w-full py-2 bg-[#1F3A5F] text-white text-xs rounded-lg">Aceptar</button></div></div></div></div></template>
<script setup>import{computed,onMounted,reactive,ref}from'vue';import api from '../../services/api';const suppliers=ref([]),products=ref([]),supplier=ref(''),date=ref(new Date().toISOString().slice(0,10)),doc=ref(''),modal=ref(false),correlativo=ref(''),error=ref(''),line=reactive({code:'',qty:10,cost:5}),cart=ref([]);const product=id=>products.value.find(p=>String(p.id_producto)===String(id))||{};const total=computed(()=>cart.value.reduce((s,i)=>s+Number(i.qty)*Number(i.cost),0));const money=n=>'$'+Number(n||0).toFixed(2);async function load(){error.value='';try{const{data}=await api.get('/api/entradas/catalogos');suppliers.value=data.proveedores||[];products.value=data.productos||[];if(suppliers.value.length&&!supplier.value)supplier.value=suppliers.value[0].id_proveedor;if(products.value.length&&!line.code)line.code=products.value[0].id_producto}catch(e){error.value=e.response?.data?.message||'No fue posible cargar los datos.'}}function add(){if(!line.code||Number(line.qty)<=0||Number(line.cost)<0)return;const e=cart.value.find(i=>String(i.code)===String(line.code));if(e){e.qty+=Number(line.qty);e.cost=Number(line.cost)}else cart.value.push({code:line.code,qty:Number(line.qty),cost:Number(line.cost)})}async function confirm(){if(!cart.value.length)return;try{const{data}=await api.post('/api/entradas',{id_proveedor:supplier.value,fecha:date.value,referencia:doc.value||null,detalles:cart.value.map(i=>({id_producto:i.code,cantidad:i.qty,costo_unitario:i.cost}))});correlativo.value=data.numero;cart.value=[];doc.value='';modal.value=true;await load()}catch(e){error.value=Object.values(e.response?.data?.errors||{}).flat()[0]||e.response?.data?.message||'No fue posible registrar la entrada.'}}onMounted(load)</script>
<style scoped>label{display:flex;flex-direction:column;gap:.25rem;font-size:.75rem;font-weight:600;text-transform:uppercase;color:#334155}.normal{font-size:.6875rem;text-transform:none;font-weight:400;color:#64748b}input,select{width:100%;padding:.625rem;border:1px solid #cbd5e1;border-radius:.5rem;font-size:.75rem;background:white;text-transform:none;font-weight:400}.modal{position:fixed;inset:0;z-index:50;display:flex;align-items:center;justify-content:center;background:#0f172a99;backdrop-filter:blur(3px);padding:1rem}.modal-card{width:100%;overflow:hidden;border-radius:.75rem;background:white;box-shadow:0 25px 50px #0004}.modal-head{display:flex;justify-content:space-between;align-items:center;background:#1F3A5F;padding:1rem 1.5rem;color:white;font-size:.875rem;font-weight:700}</style>